 "content": "def transform(grid):
    """Draw a red separator across a blank row separating aligned 2-shapes."""
    out = [row[:] for row in grid]
    height = len(grid)
    for r in range(1, height - 1):
        if all(cell == 0 for cell in grid[r]):
            if any(cell == 2 for cell in grid[r - 1]) and any(cell == 2 for cell in grid[r + 1]):
                out[r] = [3] * len(grid[r])
    return out
